        </SelectTrigger>
        <SelectContent>
          {themeItemsWithDisabled.map(item => (
            <SelectItemWithIcon
              key={item.value}
              value={item.value}
              disabled={item.value === 'disabled'}>
              {item.label}
            </SelectItemWithIcon>
          ))}
        </SelectContent>
      </Select>

      <FieldDescription className={fieldConfig.default.description}>
        Helper text
      </FieldDescription>
    </FieldSet>
  );
}

export function SelectMultipleDemo() {
  const [value, setValue] = React.useState<string[]>([]);

  return (
    <FieldSet className={`w-full max-w-sm ${fieldConfig.default.gap}`}>
      <FieldTitle className={fieldConfig.default.label}>Languages</FieldTitle>

      <Select
        multiple
        items={languageItems}
        value={value}
        onValueChange={v => setValue(v as string[])}>
        <SelectTrigger className="w-[280px]">
          <SelectValue placeholder="Select languages">
            {value.length > 0 ? (
              <span className="flex items-center gap-2">
                <Tag
                  variant="secondary"
                  size="xs"
                  pill
                  onRemove={e => {
                    e.stopPropagation();
                    setValue([]);
                  }}>
                  <span className="pl-1">{value.length}</span>
                </Tag>

                <span className="truncate">items selected</span>
              </span>
            ) : null}
          </SelectValue>
        </SelectTrigger>

        <SelectContent>
          {languageItems.map(item => (
            <SelectItem key={item.value} value={item.value}>
              <Checkbox
                id={`select-lang-${item.value}`}
                size="default"
                checked={value.includes(item.value)}
                onCheckedChange={() => {}}
                tabIndex={-1}
                className="pointer-events-none"
              />

              <SelectItemText>
                <FieldLabel
                  htmlFor={`select-lang-${item.value}`}
                  className="paragraph-regular-primary pointer-events-none">
                  {item.label}
                </FieldLabel>
              </SelectItemText>
            </SelectItem>
          ))}
        </SelectContent>
      </Select>

      <FieldDescription className={fieldConfig.default.description}>
        Select one or more programming languages
      </FieldDescription>
    </FieldSet>
  );
}
